						Debug( LDAP_DEBUG_ANY, "unable to parse remove-sids=\"%s\".\n", arg );
						return -1;
					}
					sids_to_remove[u] = 1;
					update_ctxcsn = 1;
				} while ( (arg = strtok( NULL, "," )) );
			}
			break;

		default:
			Debug( LDAP_DEBUG_ANY, "remove-sids meaningless for tool.\n" );
			break;
		}

	} else {
		return -1;
	}

	return 0;
